import {
	CreditTransactionSubType,
	CreditTransactionType
} from '@/generated/graphql'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { Coins } from 'lucide-react-native'
import { Text, View } from 'react-native'
import { creditTransactionFormatting, humanizeCredits } from '../utils/format'
import { Image } from 'expo-image'

type IntegrationItemProps = {
	usage: {
		amount: string
		type: CreditTransactionType
		average: string
		subType: CreditTransactionSubType | null
	}
}

export const IntegrationItem = ({ usage }: IntegrationItemProps) => {
	const { theme } = useTheme()

	if (
		!usage.subType ||
		usage.subType === CreditTransactionSubType.GPT_IMAGE_1 ||
		usage.subType === CreditTransactionSubType.GOOGLE_GEMINI_2_5_FLASH_IMAGE ||
		usage.subType === CreditTransactionSubType.GPT_IMAGE_1_5
	) {
		return null
	}
	const { name, thumbnail } = creditTransactionFormatting[usage.subType]

	return (
		<View style={styles.integrationItem(theme)}>
			<View style={styles.integrationItemThumbnailContainer}>
				<Image
					source={thumbnail}
					style={styles.integrationItemThumbnail(theme)}
				/>
				<Text style={styles.integrationItemSubTypeText(theme)}>{name}</Text>
			</View>
			<View style={styles.integrationItemAmountContainer}>
				<View style={styles.integrationLabelContainer}>
					<Text style={styles.integrationLabelText(theme)}>Credits used</Text>
					<Text style={styles.integrationValueText(theme)}>
						{humanizeCredits(usage.amount)}
					</Text>
				</View>
				<View style={styles.integrationLabelContainer}>
					<Text style={styles.integrationLabelText(theme)}>
						Average credits per run
					</Text>
					<View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
						<Coins size={16} color={colors[theme].gray[900]} />
						<Text style={styles.integrationValueText(theme)}>
							{humanizeCredits(usage.average)}
						</Text>
					</View>
				</View>
			</View>
		</View>
	)
}

const styles = defineStyles({
	integrationItem: (theme: Theme) => ({
		padding: 16,
		borderRadius: 24,
		borderWidth: 1,
		borderColor: colors[theme].gray[50],
		gap: 16
	}),
	integrationItemThumbnailContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 10
	},
	integrationItemSubTypeText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	integrationLabelContainer: {
		gap: 4
	},
	integrationLabelText: (theme: Theme) => ({
		fontSize: 14,
		fontWeight: '500',
		color: colors[theme].gray[400]
	}),
	integrationValueText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	integrationItemAmountContainer: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center'
	},
	integrationItemThumbnail: (theme: Theme) => ({
		width: 26,
		height: 26,
		borderRadius: 8,
		backgroundColor: colors[theme].gray[900]
	})
})
